<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
const props=defineProps({pluginId:{type:String,required:true},host:{type:Object,required:true}})
const CronInput=computed(()=>props.host.ui.CronInput)
const FEATURES=[
  {key:'episode_fix',title:'剧集季集',desc:'扫描 SxxExx 文件名，校正 Emby 识别错误',tone:'mint'},
  {key:'delete_episode_genre',title:'单集 Genre',desc:'清理剧集单集上冗余的 Genre',tone:'amber',danger:true},
  {key:'genre_mapper',title:'Genre 映射',desc:'批量替换或删除指定类型',tone:'blue'},
  {key:'season_renamer',title:'季名刮削',desc:'从 TMDB 获取季名并写入 Emby',tone:'violet',tmdb:true},
  {key:'country_scraper',title:'国家与语言',desc:'从 TMDB 获取信息并转换为标签',tone:'cyan',tmdb:true},
  {key:'alt_renamer',title:'中文别名',desc:'将 TMDB 中文别名写入 SortName',tone:'rose',tmdb:true},
  {key:'strm_mediainfo',title:'STRM 刷新',desc:'重新提取 STRM 文件媒体信息',tone:'lime'},
  {key:'damaged_check',title:'健康检查',desc:'检测缺少简介、年份等关键元数据',tone:'slate'},
  {key:'category_covers',title:'分类封面',desc:'用本地固定模板生成 Genre / Tag 封面并上传到 Emby',tone:'rose'},
]
const DEFAULTS={emby_server:'',api_key:'',user_id:'',tmdb_key:'',library_names:'',lock_modified_fields:true,max_output:50,genre_mapping_json:'{\n  "Sci-Fi & Fantasy": "科幻",\n  "War & Politics": "战争"\n}',genre_remove_list:'',add_hant_title:true,strm_delay:3,enable_episode_fix:true,enable_delete_episode_genre:false,enable_genre_mapper:false,enable_season_renamer:false,enable_country_scraper:false,enable_alt_renamer:false,enable_strm_mediainfo:false,enable_damaged_check:false,enable_category_covers:false,category_cover_types:'genre,tag',enable_auto_schedule:false,schedule_cron:'0 3 * * *',schedule_functions:[]}
const form=reactive({...DEFAULTS}),status=reactive({running:false,task:'',scheduled:false,schedule:'',history:[]})
const tab=ref('console'),selected=ref('episode_fix'),loading=ref(true),saving=ref(false),testing=ref(false),busy=ref('')
const secretVisible=reactive({api_key:false,tmdb_key:false})
const rawIds=ref(''),includeChildren=ref(false),repairConfirmed=ref(false),previewToken=ref(''),previewRequest=ref(null),repairError=ref('')
let timer
const current=computed(()=>FEATURES.find(x=>x.key===selected.value)||FEATURES[0])
const enabledCount=computed(()=>FEATURES.filter(x=>form['enable_'+x.key]).length)
const libraries=computed(()=>form.library_names.split(/[\n,]/).map(x=>x.trim()).filter(Boolean))
const operationBlocked=computed(()=>loading.value||status.running||Boolean(busy.value)||saving.value||testing.value)
const lockRepair=computed(()=>status.lock_repair||{})
const repairIds=computed(()=>[...new Set(rawIds.value.split(/[,，\s]+/).filter(Boolean))])
const repairSignature=computed(()=>JSON.stringify([rawIds.value,includeChildren.value]))
const repairInputError=computed(()=>!repairIds.value.length?'请先填写已核对的条目 ID。':repairIds.value.length>500?'一次最多填写 500 个不同的条目 ID，请分批操作。':'')
const previewItems=computed(()=>Array.isArray(lockRepair.value.items)?lockRepair.value.items.slice(0,100):[])
const canApplyRepair=computed(()=>!operationBlocked.value&&repairConfirmed.value&&Boolean(previewToken.value)&&previewToken.value===lockRepair.value.token&&lockRepair.value.ok&&Number(lockRepair.value.count)>0)
const notify=(type,msg)=>props.host.toast?.[type]?.(msg)
async function refresh(){try{Object.assign(status,await props.host.callApi('/status'));const pending=previewRequest.value;if(pending&&pending.signature===repairSignature.value&&!status.running&&lockRepair.value.ok&&lockRepair.value.token&&lockRepair.value.token!==pending.previousToken){previewToken.value=lockRepair.value.token;previewRequest.value=null}}catch{}finally{loading.value=false}}
async function load(){try{const saved={...await props.host.getConfig()};for(const field of Object.keys(secretVisible)){if(saved?.[field]==='********')saved[field]=await props.host.revealSecret(field)}if(typeof saved.lock_modified_fields!=='boolean'&&typeof saved.fix_lock_data==='boolean')saved.lock_modified_fields=saved.fix_lock_data;delete saved.fix_lock_data;Object.assign(form,DEFAULTS,saved)}catch(e){notify('error','读取配置失败：'+e.message)}await refresh();timer=setInterval(refresh,2500)}
async function save(){if(operationBlocked.value)return;saving.value=true;try{const payload=JSON.parse(JSON.stringify(form));delete payload.fix_lock_data;await props.host.saveConfig(payload);notify('success','配置已保存并应用')}catch(e){notify('error','保存失败：'+e.message)}finally{saving.value=false}}
async function test(){if(operationBlocked.value)return;testing.value=true;try{const r=await props.host.callApi('/test',{method:'POST'});notify(r.ok?'success':'error',r.message)}catch(e){notify('error','测试失败：'+e.message)}finally{testing.value=false}}
async function run(action){if(operationBlocked.value)return;const f=FEATURES.find(x=>x.key===action);if(f?.danger&&!confirm(`“${f.title}”会修改 Emby 数据，确定继续？`))return;busy.value=action;try{const r=await props.host.callApi('/run',{method:'POST',body:{action}});notify(r.ok?'success':'error',r.message);await refresh()}catch(e){notify('error','启动失败：'+e.message)}finally{busy.value=''}}
function toggleSchedule(key){const i=form.schedule_functions.indexOf(key);i<0?form.schedule_functions.push(key):form.schedule_functions.splice(i,1)}
watch([rawIds,includeChildren],()=>{previewToken.value='';previewRequest.value=null;repairConfirmed.value=false;repairError.value=''}, {flush:'sync'})
async function previewLocks(){
  if(operationBlocked.value)return
  repairConfirmed.value=false;previewToken.value='';previewRequest.value=null;repairError.value=''
  if(repairInputError.value){repairError.value=repairInputError.value;return}
  const request={signature:repairSignature.value,previousToken:lockRepair.value.token}
  busy.value='locks-preview'
  try{const r=await props.host.callApi('/locks/preview',{method:'POST',body:{item_ids:rawIds.value,include_children:includeChildren.value}});if(r.ok&&r.started){previewRequest.value=request;notify('success',r.message||'预览已在后台开始，请等待结果。');await refresh()}else{repairError.value=r.message||'预览未能启动，请检查配置后重试';notify('error',repairError.value)}}catch(e){repairError.value='预览启动失败：'+e.message;notify('error',repairError.value)}finally{busy.value=''}
}
async function applyLocks(){
  if(!canApplyRepair.value)return
  if(!confirm(`将先备份，再解除预览中的 ${lockRepair.value.count} 个条目的整体锁。原有字段锁会保留；其中也可能有人工设置的整体锁。确定已逐项核对并继续？`))return
  const token=previewToken.value;previewToken.value='';repairConfirmed.value=false;repairError.value='';busy.value='locks-apply'
  try{const r=await props.host.callApi('/locks/apply',{method:'POST',body:{token,confirmed:true}});if(r.ok&&r.started){notify('success',r.message||'修复已在后台开始，请等待执行结果。');await refresh()}else{repairError.value=r.message||'修复未能启动，请重新预览后重试';notify('error',repairError.value)}}catch(e){repairError.value='修复请求未能确认：'+e.message+'。请先查看后台结果，不要重复提交。';notify('error',repairError.value)}finally{busy.value=''}
}
async function downloadLockBackup(){
  if(operationBlocked.value)return
  busy.value='locks-backup';repairError.value=''
  try{const r=await props.host.callApi('/locks/backup');if(!r.ok||!r.backup)throw new Error(r.message||'还没有可下载的修复备份');const url=URL.createObjectURL(new Blob([JSON.stringify(r.backup,null,2)],{type:'application/json;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='emby-lock-repair-backup.json';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('success','备份下载已开始，请妥善保存')}catch(e){repairError.value='下载备份失败：'+e.message;notify('error',repairError.value)}finally{busy.value=''}
}
onMounted(load);onBeforeUnmount(()=>clearInterval(timer))
</script>

<template><div class="shell">
  <header class="hero">
    <div class="brand"><div class="mark"><svg viewBox="0 0 32 32"><path d="M8 5h11a6 6 0 0 1 0 12H8zM8 17h13a5 5 0 0 1 0 10H8z"/></svg></div><div><span class="eyebrow">MEDIA OPERATIONS</span><h1>Emby 工具箱</h1><p>把扫描、修复和刮削收进一个可观测的维护工作台。</p></div></div>
    <div class="hero-actions"><span class="state" :class="{live:status.running}"><i></i>{{status.running?status.task:'就绪'}}</span><button class="ghost" :disabled="operationBlocked" @click="test">{{testing?'正在连接…':'测试 Emby'}}</button><button class="primary" :disabled="operationBlocked" @click="save">{{saving?'保存中…':'保存并应用'}}</button></div>
  </header>
  <nav class="tabs"><button v-for="x in [['console','维护台'],['connection','连接与策略'],['locks','误锁修复'],['history','运行记录']]" :class="{active:tab===x[0]}" @click="tab=x[0]">{{x[1]}}</button></nav>
  <main v-if="tab==='console'" class="console">
    <section class="rail panel"><div class="section-head"><div><span class="kicker">MODULES</span><h2>维护模块</h2></div><b>{{enabledCount}} / {{FEATURES.length}}</b></div>
      <button v-for="f in FEATURES" class="feature" :class="[{active:selected===f.key},f.tone]" @click="selected=f.key"><i></i><span><strong>{{f.title}}</strong><small>{{form['enable_'+f.key]?'已启用':'未启用'}}</small></span><em>›</em></button>
    </section>
    <section class="workspace panel"><div class="workspace-top"><div><span class="kicker">ACTIVE MODULE</span><h2>{{current.title}}</h2><p>{{current.desc}}</p></div><label class="switch"><input v-model="form['enable_'+current.key]" type="checkbox"><span></span></label></div>
      <div class="scope"><span>作用范围</span><strong>{{libraries.length?`${libraries.length} 个指定媒体库`:'全部媒体库'}}</strong><small v-if="current.tmdb">TMDB 密钥必需</small></div>
      <div v-if="current.key==='genre_mapper'" class="two"><label>Genre 映射 JSON<textarea v-model="form.genre_mapping_json" rows="7" spellcheck="false"/></label><label>要删除的 Genre<textarea v-model="form.genre_remove_list" rows="7" placeholder="每行一个"/></label></div>
      <div v-else-if="current.key==='category_covers'" class="cover-options"><label>生成范围<select v-model="form.category_cover_types"><option value="genre,tag">Genre 与 Tag</option><option value="genre">仅 Genre</option><option value="tag">仅 Tag</option></select></label><p class="hint">图片由插件本地模板渲染，不调用 AI；会覆盖分类当前 Primary 封面。</p></div>
      <div v-else-if="current.key==='strm_mediainfo'" class="field"><label>STRM 请求间隔</label><div class="range"><input v-model.number="form.strm_delay" type="range" min="0" max="30"><output>{{form.strm_delay}} 秒</output></div></div>
      <div v-else class="note"><svg viewBox="0 0 24 24"><path d="M12 3v18M3 12h18"/></svg><p>{{current.key==='damaged_check'?'只读检查，不会修改媒体库。':'启用后可单独运行，也可纳入定时维护计划。'}}</p></div>
      <div class="workspace-bottom"><label class="check"><input type="checkbox" :checked="form.schedule_functions.includes(current.key)" @change="toggleSchedule(current.key)"><span>加入定时计划</span></label><div><button v-if="current.key==='episode_fix'" class="ghost" :disabled="operationBlocked" @click="run('scan_episode_mismatch')">先扫描</button><button class="primary" :disabled="operationBlocked" @click="run(current.key)">{{busy===current.key?'启动中…':'立即执行'}}</button></div></div>
    </section>
    <aside class="plan panel"><span class="kicker">AUTOMATION</span><h2>维护计划</h2><label class="switch-row"><span><strong>定时执行</strong><small>{{status.scheduled?'已注册到平台':'未注册'}}</small></span><label class="switch"><input v-model="form.enable_auto_schedule" type="checkbox"><span></span></label></label><label class="field">五段 Cron<component :is="CronInput" v-model="form.schedule_cron" /></label><div class="queue"><span>待执行模块</span><b>{{form.schedule_functions.length}}</b></div><button class="wide" :disabled="operationBlocked||!form.schedule_functions.length" @click="run('scheduled')">立即运行当前计划</button></aside>
  </main>
  <main v-else-if="tab==='connection'" class="settings panel"><div class="settings-title"><span class="kicker">CONNECTION</span><h2>Emby 与 TMDB</h2><p>敏感数据仅保存在平台插件配置中。</p></div><div class="form-grid"><label class="span2">Emby 地址<input v-model.trim="form.emby_server" placeholder="https://emby.example.com"></label><label>API Key<div class="secret"><input v-model="form.api_key" :type="secretVisible.api_key?'text':'password'"><button type="button" :aria-label="secretVisible.api_key?'隐藏 API Key':'显示 API Key'" @click="secretVisible.api_key=!secretVisible.api_key"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button></div></label><label>用户 ID <input v-model.trim="form.user_id" placeholder="留空自动获取"></label><label>TMDB API Key<div class="secret"><input v-model="form.tmdb_key" :type="secretVisible.tmdb_key?'text':'password'"><button type="button" :aria-label="secretVisible.tmdb_key?'隐藏 TMDB API Key':'显示 TMDB API Key'" @click="secretVisible.tmdb_key=!secretVisible.tmdb_key"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button></div></label><label class="span2">媒体库名称<textarea v-model="form.library_names" rows="5" placeholder="每行一个；留空处理全部"/></label></div><hr><div class="strategy"><label class="check"><input v-model="form.lock_modified_fields" type="checkbox"><span>仅锁定本次修改的字段</span></label><label class="check"><input v-model="form.add_hant_title" type="checkbox"><span>别名包含繁中标题</span></label><label>输出条目上限<input v-model.number="form.max_output" type="number" min="5" max="200"></label></div><p class="hint lock-policy">只维护 LockedFields，不新增条目整体锁；保留用户已有的整体锁。旧版造成的误锁不会自动解除，请在“误锁修复”中先核对、预览。</p></main>
  <main v-else-if="tab==='locks'" class="settings panel lock-repair">
    <div class="settings-title"><h2>历史误锁修复</h2><p>只处理你明确指定并确认的条目，不会自动全库解锁。</p></div>
    <div class="repair-warning"><strong>先核对来源，再解除整体锁</strong><p>历史整体锁的来源无法自动判定。请只填写你已确认被旧版工具箱影响的条目 ID；手动设置的整体锁也可能被解除，必须逐项核对。</p><p>修复保留 LockedFields 字段锁，不主动刷新元数据，也不直接修改磁盘 NFO；Emby 自身是否同步保存 NFO 由其保存器设置决定。旧 NFO 中仍有 lockdata 时，后续重新导入可能再次锁定。</p></div>
    <label class="field" for="emby-lock-repair-ids">已确认需要修复的条目 ID<textarea id="emby-lock-repair-ids" v-model="rawIds" rows="5" maxlength="50000" :disabled="operationBlocked" spellcheck="false" placeholder="例如：268389, 268390；也可每行一个 ID" aria-describedby="emby-lock-repair-help"/></label>
    <p id="emby-lock-repair-help" class="repair-help">用逗号、空格或换行分隔，每次最多 500 个不同 ID。当前填写 {{repairIds.length}} 个；此操作不使用“媒体库名称”筛选。</p>
    <label class="check"><input v-model="includeChildren" type="checkbox" :disabled="operationBlocked"><span>同时检查指定剧集或季下，字段锁为空的季 / 单集（默认不勾选）</span></label>
    <div class="repair-actions"><button class="ghost" :disabled="operationBlocked||Boolean(repairInputError)" @click="previewLocks">{{busy==='locks-preview'?'正在启动预览…':'只预览，不修改'}}</button><button class="ghost" :disabled="operationBlocked" @click="downloadLockBackup">{{busy==='locks-backup'?'准备下载…':'下载最近一次备份'}}</button></div>
    <p v-if="repairError" class="repair-error" role="alert">{{repairError}}</p>
    <p v-if="status.running" class="hint" role="status">后台任务进行中：{{status.task||'请等待'}}。提交成功不代表已经完成，最终结果会在下方自动更新。</p>
    <section v-if="lockRepair.message||lockRepair.token" class="repair-result" aria-live="polite">
      <h3>预览与执行结果</h3><p>{{lockRepair.message}}</p>
      <template v-if="lockRepair.token"><p>候选条目 {{lockRepair.count||0}} 项：指定条目 {{lockRepair.root_count||0}} 项，下级条目 {{lockRepair.child_count||0}} 项。</p><p class="repair-help">列表仅展示前 100 项，不代表完整清单。预览有有效期；任何输入变化后都必须重新预览。</p></template>
      <ul v-if="previewItems.length" class="repair-items"><li v-for="item in previewItems" :key="item.id"><div><strong>{{item.name||'未命名条目'}}</strong><span>{{item.type}} · ID {{item.id}}</span></div><p>保留字段锁：{{Array.isArray(item.fields)&&item.fields.length?item.fields.join('、'):'无'}}</p><p v-if="item.reason">{{item.reason}}</p></li></ul>
      <p v-if="lockRepair.token&&!previewToken&&!status.running" class="repair-help">此预览不能直接执行。请按当前输入重新预览，再确认修复。</p>
      <label class="check repair-confirm"><input v-model="repairConfirmed" type="checkbox" :disabled="operationBlocked||!previewToken"><span>我已逐项核对，确认这些整体锁属于误锁，并理解手动锁也可能被解除。</span></label>
      <button class="primary" :disabled="!canApplyRepair" @click="applyLocks">{{busy==='locks-apply'?'正在启动修复…':'备份并解除这些整体锁'}}</button>
    </section>
    <p class="repair-help">执行前会先将锁状态备份保存于平台插件存储，备份失败则不会写入 Emby。平台仅保留最近一批，请下载另存后再修复下一批；此文件供核对锁状态，不是媒体库备份或自动回滚文件。所有修复任务均为手动操作，不加入定时计划。</p>
  </main>
  <main v-else class="history panel"><div class="section-head"><div><span class="kicker">ACTIVITY</span><h2>运行记录</h2></div><span class="state" :class="{live:status.running}"><i></i>{{status.running?'运行中':'自动刷新'}}</span></div><div v-if="!status.history?.length" class="empty">还没有维护记录。运行一次任务后，结果会留在这里。</div><article v-for="row in status.history" class="run"><i :class="row.ok?'ok':'bad'"></i><div><strong>{{row.task}}</strong><span>{{row.source}} · {{row.time}}</span><pre>{{row.summary}}</pre></div></article></main>
</div></template>

<style scoped>
*{box-sizing:border-box}.shell{--bg:#0b1421;--panel:#111d2d;--line:#2a3d56;--muted:#8fa3bb;--text:#edf4fc;--mint:#4a98f3;--mint2:#9ac9ff;color:var(--text);font:14px/1.55 Inter,"PingFang SC",system-ui,sans-serif;min-height:720px;padding:4px}.hero{display:flex;align-items:center;justify-content:space-between;gap:28px;padding:24px 24px 22px;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:16px}.mark{width:52px;height:52px;border-radius:15px;background:var(--mint);display:grid;place-items:center;box-shadow:0 12px 35px #4a98f32b}.mark svg{width:29px;fill:#08182a}.eyebrow,.kicker{color:var(--mint);font-size:11px;font-weight:800;letter-spacing:.16em}.hero h1{font-size:25px;margin:1px 0}.hero p,.workspace-top p,.settings-title p{color:var(--muted);margin:0}.hero-actions{display:flex;align-items:center;gap:10px}.state{display:inline-flex;align-items:center;gap:8px;border:1px solid var(--line);border-radius:99px;padding:8px 12px;color:#a9bad0}.state i{width:7px;height:7px;border-radius:50%;background:#6f839c}.state.live i{background:var(--mint);box-shadow:0 0 0 5px #4a98f31d}.tabs{display:flex;gap:4px;padding:14px 24px}.tabs button{border:0;background:transparent;color:var(--muted);padding:9px 14px;border-radius:8px;font-weight:700;cursor:pointer}.tabs button.active{background:#17283e;color:var(--text)}button{font:inherit}.primary,.ghost,.wide{border-radius:9px;padding:10px 15px;font-weight:750;cursor:pointer}.primary{border:1px solid var(--mint);background:var(--mint);color:#08182a}.ghost{border:1px solid #3a5574;background:transparent;color:var(--text)}button:disabled{opacity:.45;cursor:not-allowed}.console{display:grid;grid-template-columns:230px minmax(380px,1fr) 270px;gap:14px;padding:0 24px 24px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px}.rail,.workspace,.plan{padding:18px}.section-head,.workspace-top{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.section-head h2,.workspace h2